WITH filtered AS (SELECT id, temp_c, humidity, pressure, status_bits, firmware, temp_c - status_bits AS temp_c_minus_status_bits FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 14:00:00') SELECT *, LEAD(pressure, 1) OVER (ORDER BY temp_c, id) AS next_pressure, ROW_NUMBER() OVER w_ordered AS row_seq, FIRST_VALUE(temp_c) IGNORE NULLS OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c, NTILE(10) OVER w_part AS pressure_bucket FROM filtered WINDOW w_ordered AS (ORDER BY temp_c_minus_status_bits, id), w_part AS (ORDER BY pressure DESC, id);
